package main

import "fmt"

func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() { defer close(out); for _, n := range nums { out <- n } }()
	return out
}

func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() { defer close(out); for n := range in { out <- n * n } }()
	return out
}

func main() {
	// Compose by feeding one stage's output into the next.
	for v := range square(gen(2, 3, 4)) {
		fmt.Println(v)
	}
	// Output:
	// 4
	// 9
	// 16
}

package main

import "fmt"

func double(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // this stage owns and closes ONLY out, never in
		for v := range in { // ends when the upstream closes in
			out <- v * 2
		}
	}()
	return out
}

func main() {
	in := make(chan int)
	go func() { defer close(in); in <- 5; in <- 6 }()
	for v := range double(in) { // range ends when double closes out
		fmt.Println(v)
	}
	// Output:
	// 10
	// 12
}

package main

import (
	"fmt"
	"time"
)

func produce() <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := 1; n <= 3; n++ {
			time.Sleep(10 * time.Millisecond) // stage 1 keeps producing...
			out <- n
		}
	}()
	return out
}

func main() {
	start := time.Now()
	for n := range produce() {
		time.Sleep(10 * time.Millisecond) // ...while stage 2 (consumer) processes concurrently
		_ = n
	}
	// ~40ms overlapped, not ~60ms sequential (producer & consumer run at once)
	fmt.Println(time.Since(start) < 55*time.Millisecond) // Output: true
}

package main

import (
	"context"
	"fmt"
)

func gen(ctx context.Context, nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			select {
			case out <- n: // normal send
			case <-ctx.Done(): // cancelled -> abandon the send and exit
				return
			}
		}
	}()
	return out
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	for v := range gen(ctx, 1, 2, 3, 4) {
		fmt.Println(v)
		cancel() // stop after the first value; gen's send unblocks and returns
		break
	}
	// Output: 1
}

