import "fmt"

// BUG illustration: no cancellation path.
func gen(nums ...int) <-chan int {
	out := make(chan int) // unbuffered
	go func() {
		defer close(out)
		for _, n := range nums {
			out <- n // after the consumer breaks, this blocks FOREVER -> leak
		}
	}()
	return out
}

func main() {
	for v := range gen(1, 2, 3, 4, 5) {
		fmt.Println(v)
		if v == 2 {
			break // consumer leaves early; gen's goroutine is now stranded on `out <- 3`
		}
	}
	// Output:
	// 1
	// 2
	// (gen's goroutine leaks — the fix is a ctx.Done() case on the send)
}

package main

import "fmt"

func main() {
	out := make(chan int, 2) // small smoothing buffer
	out <- 1                 // fits in buffer, does not block
	out <- 2                 // fills the buffer
	fmt.Println(len(out), cap(out)) // Output: 2 2

	// A 3rd send would block here until a receiver drains one —
	// that block IS the backpressure that throttles the upstream stage.
	<-out
	out <- 3 // now there's room again
	fmt.Println(len(out)) // Output: 2
}

