func Filter(ctx context.Context, in <-chan int, keep func(int) bool) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // close our OUTPUT on any exit path
		for v := range in { // ends when in is closed & drained
			if !keep(v) {
				continue // drop values that don't pass
			}
			select {
			case out <- v: // forward kept value
			case <-ctx.Done(): // cancelled -> stop, no leak
				return
			}
		}
	}()
	return out
}

func gen(done <-chan struct{}, nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			select {
			case out <- n:
			case <-done:
				return
			}
		}
	}()
	return out
}

func filterOdd(done <-chan struct{}, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			if n%2 == 0 {
				continue // keep only odd values
			}
			select {
			case out <- n:
			case <-done:
				return
			}
		}
	}()
	return out
}

func square(done <-chan struct{}, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			select {
			case out <- n * n:
			case <-done:
				return
			}
		}
	}()
	return out
}

// Pipeline composes the three stages: gen -> filterOdd -> square.
func Pipeline(done <-chan struct{}, nums ...int) <-chan int {
	return square(done, filterOdd(done, gen(done, nums...)))
}

